//! Canonical SPAN interfaces retain actual native and inert element identity.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse("<html><body><span id=subject data-state=initial>Fallback span</span><input id=neighbor value=seed></body></html>");d.scripting_enabled=true;let mut f=Forms::new(&d);let mut p=Page::new();let location=crate::navigation::address("https://span-interface.test/source",&crate::navigation::Location::home()).unwrap();p.set_location(&location);p.set_resource_base(&location);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
#[test]
fn span_interface_native_canonical_chain_constructor_and_records(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('subject'),C=HTMLSpanElement,P=C.prototype;if(!(x instanceof C)||Object.getPrototypeOf(x)!==P||Object.getPrototypeOf(P)!==HTMLElement.prototype||P.constructor!==C||Object.prototype.toString.call(x)!=='[object HTMLSpanElement]'||C.length!==0||x.textContent!=='Fallback span'||x.getAttribute('data-state')!=='initial')throw 'native span canonical interface';var caught=false;try{new C();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'illegal native span constructor';");}
#[test]
fn span_interface_inert_exact_namespace_and_independent_clones(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var doc=new Document(),x=doc.createElementNS('http://www.w3.org/1999/xhtml','t:span'),foreign=doc.createElementNS('urn:foreign','span'),upper=doc.createElementNS('http://www.w3.org/1999/xhtml','SPAN');if(!(x instanceof HTMLSpanElement)||Object.getPrototypeOf(x)!==HTMLSpanElement.prototype||foreign instanceof HTMLSpanElement||upper instanceof HTMLSpanElement)throw 'exact span canonical brand';x.setAttribute('data-state','actual');x.appendChild(doc.createTextNode('Child'));var copy=x.cloneNode(true);if(!(copy instanceof HTMLSpanElement)||copy===x||copy.firstChild===x.firstChild||copy.ownerDocument!==doc||copy.getAttribute('data-state')!=='actual')throw 'real span copy interface';");}
#[test]
fn span_interface_created_native_adoption_import_and_template_keep_owner_records(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.createElement('span'),C=HTMLSpanElement;x.setAttribute('data-state','kept');x.appendChild(document.createTextNode('Created'));var attr=x.getAttributeNode('data-state'),first=x.firstChild,doc=new Document();if(!(x instanceof C)||doc.adoptNode(x)!==x||x.ownerDocument!==doc||x.getAttributeNode('data-state')!==attr||attr.ownerDocument!==doc||x.firstChild!==first)throw 'span identity adoption';var copy=document.importNode(x,true),template=document.createElement('template');if(!(copy instanceof C)||copy.ownerDocument!==document||copy.firstChild===first||copy.getAttributeNode('data-state')===attr)throw 'span native import';var copyFirst=copy.firstChild,refused=false;try{template.content.appendChild(copy);}catch(e){refused=e.name==='NotSupportedError';}if(!refused||copy.parentNode!==null||copy.firstChild!==copyFirst||copy.ownerDocument!==document||template.content.firstChild!==null)throw 'deep native template guard';var leaf=copy.cloneNode(false);template.content.appendChild(leaf);document.body.appendChild(template);if(!(leaf instanceof C)||leaf.ownerDocument!==template.content.ownerDocument||leaf.getAttribute('data-state')!=='kept')throw 'span parked leaf interface';");}

#[test]
fn span_interface_constructor_descriptors_share_the_real_html_chain(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('subject'),C=HTMLSpanElement,P=C.prototype,g=Object.getOwnPropertyDescriptor(window,'HTMLSpanElement'),a=Object.getOwnPropertyDescriptor(C,'prototype'),tag=Object.getOwnPropertyDescriptor(P,Symbol.toStringTag);if(g.enumerable||!g.writable||!g.configurable||g.value!==C||a.writable||a.enumerable||a.configurable||a.value!==P||Object.getPrototypeOf(C)!==HTMLElement||C.name!=='HTMLSpanElement'||tag.value!=='HTMLSpanElement'||tag.writable||tag.enumerable||!tag.configurable||P.constructor!==C)throw 'canonical span descriptor chain';var caught=false;try{C();}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'illegal bare span constructor';var upper=document.createElement('SPAN');if(!(upper instanceof C)||upper.localName!=='span')throw 'HTML factory local-name normalization';");}
#[test]
fn span_interface_guarded_prototype_and_author_constructor_keep_native_copy_kind(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('subject'),C=HTMLSpanElement,P=C.prototype,get=Element.prototype.getAttribute,clone=Node.prototype.cloneNode;");let e=p.runtime.execute("Object.setPrototypeOf(x,HTMLDivElement.prototype);",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("Native host object prototypes cannot be changed"),"{e}");p.begin_job();run(&mut d,&mut f,&mut p,"if(Object.getPrototypeOf(x)!==P)throw 'native prototype change guard';Object.defineProperty(x,'constructor',{value:HTMLDivElement,configurable:true});if(x.constructor!==HTMLDivElement||get.call(x,'data-state')!=='initial')throw 'genuine receiver keeps metadata';var copy=clone.call(x,true);if(!(copy instanceof C)||Object.getPrototypeOf(copy)!==P||copy.textContent!=='Fallback span'||copy.getAttribute('data-state')!=='initial'||copy.firstChild===x.firstChild)throw 'native span copy does not use author prototype';delete window.HTMLSpanElement;var created=document.createElement('span');if(!(created instanceof C)||Object.getPrototypeOf(created)!==P)throw 'saved canonical span after binding deletion';var fake=Object.create(P),caught=false;try{get.call(fake,'id');}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'prototype cannot create a native element';");}
#[test]
fn span_interface_child_owners_keep_distinct_canonical_interfaces_and_origin_guards(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var x=document.getElementById('subject'),frame=document.createElement('iframe');frame.hidden=true;document.body.appendChild(frame);var child=frame.contentWindow,C=child.HTMLSpanElement,get=child.Element.prototype.getAttribute;if(C===HTMLSpanElement||C.prototype===HTMLSpanElement.prototype||Object.getPrototypeOf(C.prototype)!==child.HTMLElement.prototype||Object.getPrototypeOf(C)!==child.HTMLElement||x instanceof C||get.call(x,'data-state')!=='initial')throw 'owner-realm span interface';");p.set_location(&crate::navigation::address("https://foreign-span.test/",&crate::navigation::Location::home()).unwrap());let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.begin_job();let e=p.runtime.execute("get.call(x,'data-state');",&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("origin")||e.contains("Security"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.set_location(&crate::navigation::address("https://span-interface.test/source",&crate::navigation::Location::home()).unwrap());p.begin_job();run(&mut d,&mut f,&mut p,"if(get.call(x,'data-state')!=='initial'||!(x instanceof HTMLSpanElement))throw 'saved owner recovery';");}
#[test]
fn span_interface_clone_import_promotion_refusal_is_atomic_and_recovers(){
 for tag in ["span"]{for operation in ["clone","import","promote"]{for mode in 0..5{
  // Promotion reuses reserved main slots; its node limit is tested as a no-growth success below.
  if operation=="promote"&&mode==3{continue;}
  let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var target=document.body,source,watch=new MutationObserver(function(){{}});watch.observe(target,{{childList:true}});var which='{tag}';"));
  let source=match operation{
   "clone"=>{run(&mut d,&mut f,&mut p,"source=document.getElementById('subject');");"var result=source.cloneNode(true);"},
   "import"=>{run(&mut d,&mut f,&mut p,"var doc=new Document();source=doc.createElementNS('http://www.w3.org/1999/xhtml',which);source.setAttribute('data-state','exact');source.appendChild(doc.createTextNode('Fallback'));");"var result=document.importNode(source,true);"},
   _=>{run(&mut d,&mut f,&mut p,"var doc=new Document();source=doc.createElementNS('http://www.w3.org/1999/xhtml',which);source.setAttribute('data-state','exact');source.appendChild(doc.createTextNode('Fallback'));");"var result=target.appendChild(source);"}
  };
  run(&mut d,&mut f,&mut p,"var oldParent=source.parentNode,oldFirst=source.firstChild,oldText=source.textContent,oldValue=source.getAttributeNode('data-state');");p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let retained=p.state.retained;let commits=p.state.dom_commits;let attr_count=p.state.attributes.len();let detached=p.state.detached_nodes.clone();let controls=f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>();let limit=p.state.retained_limit;let nodes=p.state.node_limit;p.begin_job();match mode{0=>p.state.host_work=0,1=>p.state.copy_work=0,2=>p.state.retained_limit=p.state.retained,3=>p.state.node_limit=d.nodes.len(),_=>p.state.execution_deadline=Some(Instant::now())};
  let e=p.runtime.execute(source,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).expect_err(&format!("{tag}/{operation}/{mode}"));assert!(e.contains("work")||e.contains("allowance")||e.contains("limit")||e.contains("bound"),"{tag}/{operation}/{mode}: {e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!((p.state.retained,p.state.dom_commits,p.state.attributes.len(),p.state.detached_nodes.clone()),(retained,commits,attr_count,detached));assert_eq!(f.controls.iter().map(|(n,c)|(*n,c.owner,c.value.text(),c.disabled,c.checked)).collect::<Vec<_>>(),controls);
  p.state.retained_limit=limit;p.state.node_limit=nodes;p.state.execution_deadline=None;p.begin_job();run(&mut d,&mut f,&mut p,"if(source.parentNode!==oldParent||source.firstChild!==oldFirst||source.textContent!==oldText||source.getAttributeNode('data-state')!==oldValue||watch.takeRecords().length)throw 'atomic span lifecycle refusal';");run(&mut d,&mut f,&mut p,source);run(&mut d,&mut f,&mut p,if operation=="promote"{"var records=watch.takeRecords();if(result!==source||source.parentNode!==target||source.firstChild!==oldFirst||source.getAttributeNode('data-state')!==oldValue||records.length!==1||records[0].addedNodes[0]!==source)throw 'promotion recovery';"}else{"if(result===source||result.parentNode!==null||result.getAttribute('data-state')!==source.getAttribute('data-state')||result.textContent!==source.textContent||source.parentNode!==oldParent||watch.takeRecords().length)throw 'copy recovery';"});
 }}}
}

#[test]
fn span_interface_reserved_main_connection_needs_no_additional_node_slots(){
 for tag in ["span"]{for inert_owner in [false,true]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var target=document.body,owner={},source=owner.createElementNS('http://www.w3.org/1999/xhtml','{tag}');source.setAttribute('data-state','exact');source.appendChild(owner.createTextNode('Reserved'));var first=source.firstChild,attr=source.getAttributeNode('data-state');",if inert_owner{"new Document()"}else{"document"}));let nodes=d.nodes.len();let limit=p.state.node_limit;p.state.node_limit=nodes;p.begin_job();run(&mut d,&mut f,&mut p,"if(target.appendChild(source)!==source||source.ownerDocument!==document||source.firstChild!==first||source.getAttributeNode('data-state')!==attr||source.getAttribute('data-state')!=='exact'||source.parentNode!==target)throw 'reserved native span connection';");assert_eq!(d.nodes.len(),nodes);p.state.node_limit=limit;}}
}

#[test]
fn span_interface_clone_import_active_content_guards_preserve_source(){
 let(mut d,mut f,mut p)=fixture();for node in &mut d.nodes{if let NodeKind::Element{tag,attrs,..}=&mut node.kind{if tag=="span"{attrs.push(crate::html::Attribute{name:crate::html::AttributeName::unqualified("onclick".into()),value:DomString::from("window.guard=1".to_owned())});}}}p.state.rebuild(&d).unwrap();run(&mut d,&mut f,&mut p,"var x=document.getElementById('subject'),doc=new Document(),source=doc.createElementNS('http://www.w3.org/1999/xhtml','span'),frame=doc.createElementNS('http://www.w3.org/1999/xhtml','iframe');source.appendChild(frame);");for code in ["x.cloneNode(true);","document.importNode(source,true);"]{let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;p.begin_job();let e=p.runtime.execute(code,&mut Bridge{doc:&mut d,forms:&mut f,state:&mut p.state}).unwrap_err();assert!(e.contains("support")||e.contains("unavailable")||e.contains("implemented"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);p.begin_job();run(&mut d,&mut f,&mut p,"if(source.firstChild!==frame||frame.parentNode!==source||source.ownerDocument!==doc||x.getAttribute('data-state')!=='initial')throw 'active content copy guard';");}
}


#[test]
fn span_interface_deferred_dispatch_event_keeps_frozen_data_identity_and_real_dispatch(){let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,"var P=EventTarget.prototype;Object.freeze(P);var a=Object.getOwnPropertyDescriptor(P,'dispatchEvent'),method=a.value,x=document.getElementById('subject');if(!a.enumerable||a.writable||a.configurable||typeof method!=='function'||method.name!=='dispatchEvent'||method.length!==1||P.dispatchEvent!==method||x.dispatchEvent!==method||Object.hasOwn(method,'prototype'))throw 'stable frozen dispatch data method';var calls=0,listener=function(e){calls++;e.preventDefault();},event=document.createEvent('Event');event.initEvent('slice',false,true);x.addEventListener('slice',listener);if(method.call(x,event)!==false||calls!==1||event.defaultPrevented!==true||event.target!==x)throw 'actual cancelable dispatch';var next=document.createEvent('Event');next.initEvent('other',false,false);if(method.call(x,next)!==true||calls!==1||next.target!==x)throw 'actual uncanceled dispatch';for(var bad of [{},Object.create(P),new Event('bad')]){var caught=false;try{method.call(bad,next);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'dispatch concrete receiver';}var caught=false;try{new method(next);}catch(e){caught=e instanceof TypeError;}if(!caught)throw 'dispatch method not constructible';");}
